22	/**
23	 * Central data-access layer (CLAUDE.md). All reads go through the RLS-enforced
24	 * server client, so each caller only sees rows they're entitled to. Public
25	 * provider reads select PUBLIC_PROVIDER_COLUMNS — never the server-only
26	 * bg_check_ref / payout_account_ref (no column-level RLS, so we scope here).
27	 */
28	
29	/** Approved providers for discovery, with optional filters. */
30	export async function listApprovedProviders(
31	  filters: BrowseFilters = {},
32	): Promise<PublicProvider[]> {
33	  const supabase = await createClient();
34	  let query = supabase
35	    .from("providers")
36	    .select(PUBLIC_PROVIDER_COLUMNS)
37	    .eq("status", "approved");
38	
39	  if (filters.topic) query = query.contains("topics", [filters.topic]);
40	  if (filters.language) query = query.contains("languages", [filters.language]);
41	  if (filters.availableNow) query = query.eq("is_available_now", true);
42	  if (typeof filters.maxPriceCents === "number") {
43	    query = query.lte("price_block_30_cents", filters.maxPriceCents);
44	  }
45	
46	  const { data, error } = await query.order("rating_avg", { ascending: false });
47	  if (error) throw error;
48	  return (data ?? []) as unknown as PublicProvider[];
49	}
50	
51	/** A single approved provider's public profile, or null. */
52	export async function getApprovedProvider(
53	  id: string,
54	): Promise<PublicProvider | null> {
55	  const supabase = await createClient();
56	  const { data, error } = await supabase
57	    .from("providers")
58	    .select(PUBLIC_PROVIDER_COLUMNS)
59	    .eq("id", id)
60	    .eq("status", "approved")
61	    .maybeSingle();
62	  if (error) throw error;
63	  return (data as unknown as PublicProvider | null) ?? null;
64	}
